bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 60
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import pg from 'pg';import {readFileSync} from 'node:fs';
import {setDefaultResultOrder} from 'node:dns';import {setDefaultAutoSelectFamily} from 'node:net';
import {createCreatorTelegramFetch} from '/opt/videobot/src/runtime/creatorEgress.mjs';
setDefaultResultOrder('ipv4first');setDefaultAutoSelectFamily(false);
const outbound=createCreatorTelegramFetch(),e=process.env;
const db=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,database:e.VIDEOBOT_DB_NAME,password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:5000});
try{
 const rows=(await db.query("SELECT l.telegram_transaction_id,l.buyer_user_id,l.stars,l.delivery_key FROM videobot_stars_ledger l WHERE l.listing_id=(SELECT listing_id FROM videobot_post_receipts WHERE paid_message_id=$1) AND l.kind=$2",[4691,'paid'])).rows;
 if(!rows.length)process.exitCode=61;
 else{
  const token=readFileSync('/run/secrets/videobot_telegram_token','utf8').trim();
  const base=e.VIDEOBOT_LOCAL_API_URL??'https://api.telegram.org';
  const transactions=[];
  let complete=false;
  for(let i=0;i<3;i++){
   const response=await outbound.fetch(base+'/bot'+token+'/getStarTransactions',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({offset:i*100,limit:100}),signal:AbortSignal.timeout(30000)});
   const j=await response.json();
   if(j?.ok!==true||!Array.isArray(j.result?.transactions)){process.exitCode=62;break}
   transactions.push(...j.result.transactions);
   if(j.result.transactions.length<100){complete=true;break}
  }
  if(!process.exitCode){
   const matches=rows.map(x=>transactions.filter(t=>t.id===x.telegram_transaction_id&&t.amount===Number(x.stars)&&t.source?.type==='user'&&t.source?.transaction_type==='paid_media_payment'&&String(t.source?.user?.id)===String(x.buyer_user_id)&&t.source?.paid_media_payload===x.delivery_key).length);
   if(matches.some(n=>n>1))process.exitCode=71;
   else if(matches.every(n=>n===1))console.log('OFFICIAL_STARS_TRANSACTIONS_MATCH_LEDGER=PASS');
   else if(complete)process.exitCode=72;
   else process.exitCode=73;
  }
 }
}catch(e){console.error('STARS_RECONCILIATION_ERROR_CLASS='+String(e?.code??'OTHER').slice(0,12));process.exitCode=79}
finally{await outbound.close();await db.end()}
JS
